Suggested-by: Florian Westphal <fw@strlen.de>
Fixes: acf568ee859f ("xfrm: Reinject transport-mode packets through tasklet")
Cc: stable@vger.kernel.org
Signed-off-by: Qi Tang <tpluszz77@gmail.com>
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>

Here is the root cause:
After async crypto completes, the code calls dev_put(skb->dev) immediately upon resumption (encap_type == -1) before transport_finish's NF_HOOK, causing a use-after-free when NF_HOOK accesses skb->dev.

Here is the patch:
  */
 int xfrm_input(struct sk_buff *skb, int nexthdr, __be32 spi, int encap_type)
 {
 	const struct xfrm_state_afinfo *afinfo;
 	struct net *net = dev_net(skb->dev);
 	int err;
 	__be32 seq;
 	__be32 seq_hi;
 	struct xfrm_state *x = NULL;
 	xfrm_address_t *daddr;
 	u32 mark = skb->mark;
 	unsigned int family = AF_UNSPEC;
 	int decaps = 0;
 	int async = 0;
 	bool xfrm_gro = false;
 	bool crypto_done = false;
 	struct xfrm_offload *xo = xfrm_offload(skb);
 	struct sec_path *sp;

 	if (encap_type < 0 || (xo && (xo->flags & XFRM_GRO || encap_type == 0 ||
 				      encap_type == UDP_ENCAP_ESPINUDP))) {
 		x = xfrm_input_state(skb);

 		if (unlikely(x->km.state != XFRM_STATE_VALID)) {
 			if (x->km.state == XFRM_STATE_ACQ)
 				XFRM_INC_STATS(net, LINUX_MIB_XFRMACQUIREERROR);
 			else
 				XFRM_INC_STATS(net,
 					       LINUX_MIB_XFRMINSTATEINVALID);

 			if (encap_type == -1)
 				dev_put(skb->dev);
 			goto drop;
 		}

 		family = x->props.family;

 		/* An encap_type of -2 indicates reconstructed inner packet */
 		if (encap_type == -2)
 			goto resume_decapped;

 		/* An encap_type of -1 indicates async resumption. */
 		if (encap_type == -1) {
 			async = 1;
-			dev_put(skb->dev);
 			seq = XFRM_SKB_CB(skb)->seq.input.low;
 			spin_lock(&x->lock);
 			goto resume;
 		}
 		/* GRO call */
 		seq = XFRM_SPI_SKB_CB(skb)->seq;

 		if (xo && (xo->flags & CRYPTO_DONE)) {
 			crypto_done = true;
 			family = XFRM_SPI_SKB_CB(skb)->family;

 			if (!(xo->status & CRYPTO_SUCCESS)) {
 				if (xo->status &
 				    (CRYPTO_TRANSPORT_AH_AUTH_FAILED |
 				     CRYPTO_TRANSPORT_ESP_AUTH_FAILED |
 				     CRYPTO_TUNNEL_AH_AUTH_FAILED |
 				     CRYPTO_TUNNEL_ESP_AUTH_FAILED)) {

 					xfrm_audit_state_icvfail(x, skb,
 								 x->type->proto);
 					x->stats.integrity_failed++;
 					XFRM_INC_STATS(net, LINUX_MIB_XFRMINSTATEPROTOERROR);
 					goto drop;
 				}

 				if (xo->status & CRYPTO_INVALID_PROTOCOL) {
 					XFRM_INC_STATS(net, LINUX_MIB_XFRMINSTATEPROTOERROR);
 					goto drop;
 				}

 				XFRM_INC_STATS(net, LINUX_MIB_XFRMINBUFFERERROR);
 				goto drop;
 			}

 			if (xfrm_parse_spi(skb, nexthdr, &spi, &seq)) {
 				XFRM_INC_STATS(net, LINUX_MIB_XFRMINHDRERROR);
 				goto drop;
 			}

 			nexthdr = x->type_offload->input_tail(x, skb);
 		}

